import test from 'node:test';
import assert from 'node:assert/strict';
import { renderForgeStudioHtml } from '../src/ui/forge-studio.mjs';

const project={id:'forge_ui',name:'UI proof',stage:'verification',revision:12,semanticRevision:9,assurance:'A3',domain:'saas',ideas:[{id:'idea-a',title:'Idea A',thesis:'Traceable agent delivery',mechanism:'compile evidence graph',cheapestExperiment:'one flow',fingerprint:'a'.repeat(64)}],artifacts:[{id:'artifact_a',type:'verification-report',state:'verified',version:2,sha256:'b'.repeat(64),consumes:['artifact_parent']}],evidence:[{id:'e1',type:'verification-report',title:'Tests',status:'pass',sha256:'c'.repeat(64),producer:{id:'reviewer'},subject:{semanticRevision:9}}],gates:[{stage:'research',status:'pass',score:100},{stage:'verification',status:'fail',score:75,evaluatedSemanticRevision:9,inputSha256:'d'.repeat(64),rules:[{id:'security-review',passed:false,remediation:'Attach review'}]}],findings:[{id:'f1',title:'Tenant leak',severity:'critical',status:'open',category:'security'}],risks:[{id:'r1',title:'Cost spike',severity:'high',status:'open',category:'cost'}]};

test('Studio v2 derives lifecycle from real gate records and exposes proof, lineage, project switching, and execution controls',()=>{const html=renderForgeStudioHtml({projects:[project,{...project,id:'forge_other',name:'Other'}],project,routes:[{name:'testing-tenant-isolation',score:99,reasons:['target:security-review']}]});assert.match(html,/Project<select id="project-selector"/);assert.match(html,/security-review/);assert.match(html,/artifact_parent/);assert.match(html,/reviewer · revision 9/);assert.match(html,/Tenant leak/);assert.match(html,/Cost spike/);assert.match(html,/forge_skill_run_start/);assert.match(html,/forge_skill_get/);assert.match(html,/setWidgetState/);assert.doesNotMatch(html,/unsafe-inline/);assert.match(html,/Content-Security-Policy/);});

test('Studio v2 never marks an unevaluated earlier stage as passed by index alone',()=>{const html=renderForgeStudioHtml({project:{...project,gates:[{stage:'verification',status:'fail',score:50,rules:[]}]}});const discovery=html.match(/<li class="stage ([^"]+)" title="not evaluated"><span>02<\/span><strong>discovery/);assert.equal(discovery?.[1],'pending');});
